import { orderBy } from "lodash";
import { type ConversationEvent, type UnionEventType, ConversationEventType } from "../../types";
import { isConversationEvent } from "../../utils";
import type { FlowTimelineEntry } from "./types";

const isSkillEvent = (event: ConversationEvent) => {
  return (
    [
      ConversationEventType.SkillActivated,
      ConversationEventType.SkillInterrupted,
      ConversationEventType.SkillResumed,
      ConversationEventType.SkillCancelled,
      ConversationEventType.SkillCompleted,
    ].includes(event.conversationEventType) && Boolean(event.skillId)
  );
};

const isBlockEvent = (event: ConversationEvent) => {
  return (
    [
      ConversationEventType.OrderedBlockEntered,
      ConversationEventType.OrderedBlockInterrupted,
      ConversationEventType.OrderedBlockResumed,
      ConversationEventType.OrderedBlockCancelled,
      ConversationEventType.OrderedBlockCompleted,
    ].includes(event.conversationEventType) &&
    Boolean(event.skillId) &&
    Boolean(event.blockId)
  );
};

const mapEventToStatus = (event: ConversationEvent) => {
  switch (event.conversationEventType) {
    case ConversationEventType.SkillInterrupted:
    case ConversationEventType.OrderedBlockInterrupted:
      return "interrupted" as const;
    case ConversationEventType.SkillCancelled:
    case ConversationEventType.OrderedBlockCancelled:
      return "cancelled" as const;
    case ConversationEventType.SkillCompleted:
    case ConversationEventType.OrderedBlockCompleted:
      return "completed" as const;
    default:
      return "active" as const;
  }
};

const isStartEvent = (event: ConversationEvent) => {
  return [ConversationEventType.SkillActivated, ConversationEventType.OrderedBlockEntered].includes(
    event.conversationEventType,
  );
};

const isFinishedEvent = (event: ConversationEvent) => {
  return [
    ConversationEventType.SkillCompleted,
    ConversationEventType.SkillCancelled,
    ConversationEventType.OrderedBlockCompleted,
    ConversationEventType.OrderedBlockCancelled,
  ].includes(event.conversationEventType);
};

/**
 * Derives a timeline of skill and ordered-block invocations from the dedicated
 * Mantle lifecycle events. Historical Flow* compatibility events (written by
 * older Mantle versions) are ignored on purpose.
 * Returns entries in reverse chronological order (newest first).
 *
 * @param events - Flat list of conversation events
 * @param skillNames - Optional map of skillId → display name for human-readable labels
 */
export function deriveSkillTimeline(
  events?: UnionEventType[],
  skillNames?: Map<string, string>,
): FlowTimelineEntry[] {
  if (!events) {
    return [];
  }

  const invocationsByKey: { [key: string]: ConversationEvent[][] } = {};

  for (const convEvent of events) {
    if (!isConversationEvent(convEvent)) {
      continue;
    }

    if (!isSkillEvent(convEvent) && !isBlockEvent(convEvent)) {
      continue;
    }

    const key = isBlockEvent(convEvent)
      ? `block:${convEvent.skillId}/${convEvent.blockId}`
      : `skill:${convEvent.skillId}`;

    if (isStartEvent(convEvent)) {
      invocationsByKey[key] = [...(invocationsByKey[key] || []), [convEvent]];
    } else {
      invocationsByKey[key]?.at(-1)?.push(convEvent);
    }
  }

  const entries: FlowTimelineEntry[] = [];

  for (const key in invocationsByKey) {
    for (const invocationEvents of invocationsByKey[key]) {
      if (!invocationEvents?.length) continue;
      const sortedEvents = orderBy(invocationEvents, "timestamp");
      const firstEvent = sortedEvents.at(0);
      const lastEvent = sortedEvents.at(-1);
      if (!firstEvent?.skillId || !lastEvent) continue;
      const isBlock = isBlockEvent(firstEvent);
      entries.push({
        id: firstEvent.id,
        type: isBlock ? "block" : "skill",
        flowId: isBlock ? (firstEvent.blockId ?? firstEvent.skillId) : firstEvent.skillId,
        flowName: isBlock ? undefined : skillNames?.get(firstEvent.skillId),
        skillId: firstEvent.skillId,
        blockId: firstEvent.blockId,
        status: mapEventToStatus(lastEvent),
        startTime: new Date(firstEvent.timestamp),
        exactStartTime: firstEvent.originalTimestamp,
        endTime: isFinishedEvent(lastEvent) ? new Date(lastEvent.timestamp) : undefined,
      });
    }
  }

  return orderBy(entries, "exactStartTime", "desc");
}
